ce, .email-style-price {\\n  font-size: 15px;\\n  line-height: 1.4;\\n  font-weight: 500;\\n  font-variant-numeric: tabular-nums;\\n}\\n.email-style-price-base.disabled, .disabled.email-style-discount-price, .disabled.email-style-discount-old-price, .disabled.email-style-price {\\n  opacity: 0.6;\\n}\\n.email-style-price-base.negative, .negative.email-style-discount-price, .negative.email-style-discount-old-price, .negative.email-style-price {\\n  color: #f0153d;\\n}\\n\\n.email-style-price {\\n  font-weight: bold;\\n  color: {{primaryColor}};\\n}\\n\\n.email-style-discount-old-price {\\n  text-decoration: line-through;\\n  color: var(--color-gray-4, #5e5e5e);\\n}\\n\\n.email-style-discount-price {\\n  font-weight: bold;\\n  color: #ff4747;\\n  margin-left: 5px;\\n}\\n\\n.pre-wrap {\\n  white-space: pre-wrap;\\n} hr {height: 2px;background: #e7e7e7; border-radius: 1px; padding: 0; margin: 20px 0; outline: none; border: 0;} .button.primary { margin: 0; text-decoration: none; font-size: 16px; font-weight: bold; color: {{primaryColorContrast}}; padding: 0 27px; line-height: 42px; background: {{primaryColor}}; text-align: center; border-radius: 7px; touch-action: manipulation; display: inline-block; transition: 0.2s transform, 0.2s opacity; } .button.primary:active { transform: scale(0.95, 0.95); }  .inline-link, .inline-link:link, .inline-link:visited, .inline-link:active, .inline-link:hover { margin: 0; text-decoration: underline; font-size: inherit; font-weight: inherit; color: inherit; touch-action: manipulation; } .inline-link:active { opacity: 0.5; }  .description { color: #5e5e5e; } </style>\\n</head>\\n\\n<body>\\n<p style=\\\"margin: 0; padding: 0; line-height: 1.4;\\\">{{greeting}}</p><p style=\\\"margin: 0; padding: 0; line-height: 1.4;\\\"><br></p><p style=\\\"margin: 0; padding: 0; line-height: 1.4;\\\">L\'adresse e-mail de votre compte chez {{organizationName}} a été modifiée de {{email}} en {{newEmail}}. Vous vous connecterez désormais avec cette nouvelle adresse e-mail.</p><p style=\\\"margin: 0; padding: 0; line-height: 1.4;\\\"><br></p><p style=\\\"margin: 0; padding: 0; line-height: 1.4;\\\">Vous n\'êtes pas à l\'origine de ce changement ? Contactez-nous au plus vite via {{fromAddress}}.</p><p style=\\\"margin: 0; padding: 0; line-height: 1.4;\\\"><br></p><p style=\\\"margin: 0; padding: 0; line-height: 1.4;\\\">Cordialement,</p><p style=\\\"margin: 0; padding: 0; line-height: 1.4;\\\">{{organizationName}}</p>\\n</body>\\n\\n</html>\", \"text\": \"{{greeting}}\\n\\nL\'adresse e-mail de votre compte chez {{organizationName}} a été modifiée de {{email}} en {{newEmail}}. Vous vous connecterez désormais avec cette nouvelle adresse e-mail.\\n\\nVous n\'êtes pas à l\'origine de ce changement ? Contactez-nous au plus vite via {{fromAddress}}.\\n\\nCordialement,\\n{{organizationName}}\", \"json\": {\"type\": \"doc\", \"content\": [{\"type\": \"paragraph\", \"content\": [{\"type\": \"smartVariable\", \"attrs\": {\"id\": \"greeting\"}}]}, {\"type\": \"paragraph\"}, {\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"L\'adresse e-mail de votre compte chez \"}, {\"type\": \"smartVariable\", \"attrs\": {\"id\": \"organizationName\"}}, {\"type\": \"text\", \"text\": \" a été modifiée de \"}, {\"type\": \"smartVariable\", \"attrs\": {\"id\": \"email\"}}, {\"type\": \"text\", \"text\": \" en \"}, {\"type\": \"smartVariable\", \"attrs\": {\"id\": \"newEmail\"}}, {\"type\": \"text\", \"text\": \". Vous vous connecterez désormais avec cette nouvelle adresse e-mail.\"}]}, {\"type\": \"paragraph\"}, {\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Vous n\'êtes pas à l\'origine de ce changement ? Contactez-nous au plus vite via \"}, {\"type\": \"smartVariable\", \"attrs\": {\"id\": \"fromAddress\"}}, {\"type\": \"text\", \"text\": \".\"}]}, {\"type\": \"paragraph\"}, {\"type\": \"paragraph\", \"content\": [{\"type\": \"text\", \"text\": \"Cordialement,\"}]}, {\"type\": \"paragraph\", \"con